function rpgVisualPosition(entity: OfficeRpgSceneEntity) {
  const room = RPG_ROOM_LAYOUT[entity.room];
  return {
    x: room.x + (room.w * entity.positionHint.x) / 100,
    y: room.y + (room.h * entity.positionHint.y) / 100,
  };
}

function rpgVisualOverlapOffset(index: number) {
  if (index === 0) return { x: 0, y: 0 };
  const ring = Math.ceil(index / 6);
  const angle = ((index - 1) % 6) * (Math.PI / 3) - Math.PI / 6;
  const radius = 12 + ring * 6;
  return {
    x: Math.cos(angle) * radius,
    y: Math.sin(angle) * radius,
  };
}

function rpgVisualLabelLayout(entity: OfficeRpgSceneEntity, overlapIndex: number, roomIndex: number) {
  const crowdedRoom = new Set<OfficeRpgRoomId>(["agent_desks", "task_board", "cron_room", "source_archive"]).has(entity.room);
  const densityTier = crowdedRoom ? "compact" : "standard";
  const slot = crowdedRoom ? roomIndex % 10 : overlapIndex % 6;
  const compactSlots = [
    { x: 15, y: -38 },
    { x: 15, y: 31 },
    { x: -58, y: -52 },
    { x: -58, y: 47 },
    { x: 15, y: -20 },
    { x: 15, y: 63 },
    { x: -58, y: 4 },
    { x: -58, y: 78 },
    { x: -28, y: -70 },
    { x: -28, y: 92 },
  ];
  const standardSlots = [
    { x: 16, y: -44 },
    { x: 16, y: 39 },
    { x: -88, y: -60 },
    { x: -88, y: 55 },
    { x: 16, y: -26 },
    { x: 16, y: 73 },
  ];
  const label = (densityTier === "compact" ? compactSlots : standardSlots)[slot] ?? standardSlots[0];
  const width = densityTier === "compact" ? 46 : 72;
  return {
    densityRoom: crowdedRoom ? entity.room : "standard",
    densityTier,
    slot,
    labelX: label.x,
    labelY: label.y,
    width,
    labelLineStartX: label.x > 0 ? 8 : -8,
    labelLineEndX: label.x > 0 ? label.x + 1 : label.x + width - 1,
    fontSize: densityTier === "compact" ? 8 : 9,
    textX: densityTier === "compact" ? 6 : 7,
  };
}

function rpgVisualEntities(entities: OfficeRpgSceneEntity[]) {
  const seen = new Map<string, number>();
  const roomSeen = new Map<OfficeRpgRoomId, number>();
  return entities.map((entity) => {
    const base = rpgVisualPosition(entity);
    const key = `${entity.room}:${Math.round(entity.positionHint.x / 8)}:${Math.round(entity.positionHint.y / 8)}`;
    const overlapIndex = seen.get(key) ?? 0;
    const roomIndex = roomSeen.get(entity.room) ?? 0;
    seen.set(key, overlapIndex + 1);
    roomSeen.set(entity.room, roomIndex + 1);
    const offset = rpgVisualOverlapOffset(overlapIndex);
    return {
      entity,
      overlapIndex,
      roomIndex,
      labelLayout: rpgVisualLabelLayout(entity, overlapIndex, roomIndex),
      position: {
        x: base.x + offset.x,
        y: base.y + offset.y,
      },
      pose: rpgCharacterPose(entity),
    };
  });
}

function rpgCharacterPose(entity: OfficeRpgSceneEntity) {
  if (entity.status === "blocked" || entity.severity === "danger") return "blocked";
  if (entity.status === "working" || entity.status === "warning") return "active";
  if (entity.status === "waiting") return "waiting";
  return "idle";
}

