export function NasRuntimeSingleFileWriteApprovalActionPanel({
  action,
  draft,
  approved,
  busy,
  result,
  error,
  onDraftChange,
  onApprovalChange,
  onExecute,
}: {
  action: OfficeNasRuntimeSingleFileWriteApprovalAction;
  draft: OfficeNasMacRelayWritePayload;
  approved: boolean;
  busy: boolean;
  result: OfficeNasMacRelayWriteResult | null;
  error: string | null;
  onDraftChange: (field: keyof OfficeNasMacRelayWritePayload, value: string) => void;
  onApprovalChange: (approved: boolean) => void;
  onExecute: () => void;
}) {
  const fields: Array<keyof OfficeNasMacRelayWritePayload> = ["relay_request_ref", "relay_execution_ref", "write_ref", "package_ref", "target_vault_ref", "safe_slug", "safe_title", "requested_by", "requested_at", "nas_keeper_ref", "relay_node_ref", "relay_authorized_by", "relay_authorized_at"];
  return (
    <Card
      data-office-nas-runtime-single-file-write-action="true"
      data-office-nas-mac-relay-write-execute-action="true"
      data-office-nas-runtime-single-file-write-endpoint={action.endpoint}
      data-office-nas-runtime-single-file-write-enabled-controls={action.enabledControls}
      data-office-nas-runtime-single-file-write-raw-path-input-enabled={String(action.rawPathInputEnabled)}
      data-office-nas-runtime-single-file-write-credential-input-enabled={String(action.credentialInputEnabled)}
      data-office-nas-runtime-single-file-write-mount-path-input-enabled={String(action.mountPathInputEnabled)}
    >
      <CardHeader>
        <CardTitle className="flex items-center gap-2 text-base">
          <ShieldCheck className="h-4 w-4 text-emerald-300" /> {action.title}
        </CardTitle>
      </CardHeader>
      <CardContent>
        <div className="space-y-3 text-xs text-midground/75">
          <div className="border border-emerald-300/20 bg-emerald-950/10 p-3">
            <div className="font-semibold text-emerald-100">단일 파일 쓰기 · 승인 후 1회 실행</div>
            <div className="mt-1 leading-5">raw 경로/토큰 입력 금지. NAS Keeper 승인 envelope와 relay authorization safe refs만 Mac relay 실행 route로 보냅니다.</div>
            <div className="mt-1 font-mono text-[10px] text-emerald-100/70">{action.endpoint}</div>
          </div>
          <div className="grid gap-2 md:grid-cols-2">
            {fields.map((field) => (
              <label key={field} className="grid gap-1 border border-current/15 bg-black/15 p-2">
                <span className="font-mono text-[10px] uppercase tracking-[0.14em] text-midground/55">{field}</span>
                <input
                  name={field}
                  value={draft[field]}
                  onChange={(event) => onDraftChange(field, event.target.value)}
                  className="border border-current/15 bg-black/30 px-2 py-1 text-xs text-foreground"
                />
              </label>
            ))}
          </div>
          <label className="grid gap-1 border border-current/15 bg-black/15 p-2">
            <span className="font-mono text-[10px] uppercase tracking-[0.14em] text-midground/55">markdown_body</span>
            <textarea
              name="markdown_body"
              value={draft.markdown_body}
              onChange={(event) => onDraftChange("markdown_body", event.target.value)}
              className="min-h-24 border border-current/15 bg-black/30 px-2 py-1 text-xs text-foreground"
            />
          </label>
          <label className="flex items-center gap-2 border border-amber-300/20 bg-amber-950/10 p-3 text-amber-100/80">
            <input type="checkbox" name="approved" checked={approved} onChange={(event) => onApprovalChange(event.target.checked)} />
            승인: 이 safe payload를 protected API로 1회 실행
          </label>
          <button
            type="button"
            disabled={!approved || busy}
            onClick={onExecute}
            className="border border-emerald-300/30 px-3 py-2 text-xs font-semibold uppercase tracking-[0.14em] text-emerald-100 disabled:opacity-40"
          >
            {busy ? "실행 중" : "NAS Keeper → Mac relay 쓰기 실행"}
          </button>
          {error ? <div className="border border-red-300/25 bg-red-950/10 p-3 text-red-100" data-office-nas-runtime-single-file-write-error="true">{error}</div> : null}
          {result ? (
            <div className="border border-sky-300/20 bg-sky-950/10 p-3" data-office-nas-runtime-single-file-write-result="true">
              <div>executed {String(result.executed)} · written {String(result.written)}</div>
              {result.dto ? (
                <div className="mt-1 grid gap-1">
                  <span>safe display path {result.dto.safe_display_path}</span>
                  <span>safe logical path {result.dto.safe_logical_path}</span>
                  <span>bytes {result.dto.bytes_written} · readback {String(result.dto.readback_verified)} · audit {String(result.dto.audit_written)}</span>
                  <span>sha {result.dto.readback_sha256.slice(0, 12)} · first line {result.dto.readback_first_line}</span>
                  <span>rollback {String(result.dto.rollback_created)} · {result.dto.rollback_ref ?? "rollback_none"} · {result.dto.audit_ref ?? "audit_none"}</span>
                </div>
              ) : null}
              {result.errors.length > 0 ? <div className="mt-1">errors {result.errors.map((item) => `${item.field}:${item.code}`).join(" · ")}</div> : null}
            </div>
          ) : null}
        </div>
      </CardContent>
    </Card>
  );
}


type NasKeeperExecutionFromPreviewDraftField = "handoff_ref" | "relay_execution_ref" | "nas_keeper_ref" | "relay_node_ref" | "relay_authorized_by" | "relay_authorized_at";

export function NasKeeperExecutionOperatorActionPanel({
  action,
  draft,
  stateDraft,
  approved,
  recordStateAfterWrite,
  busy,
  result,
  stateBusy,
  stateResult,
  error,
  onDraftChange,
  onStateDraftChange,
  onApprovalChange,
  onRecordStateAfterWriteChange,
  onExecute,
  onRecordState,
}: {
  action: OfficeNasKeeperExecutionOperatorAction;
  draft: OfficeNasKeeperExecutionFromPreviewPayload;
  stateDraft: NasKeeperExecutionStateDraft;
  approved: boolean;
  recordStateAfterWrite: boolean;
  busy: boolean;
  result: OfficeNasKeeperExecutionFromPreviewResult | null;
  stateBusy: boolean;
  stateResult: OfficeNasKeeperExecutionStateResult | null;
  error: string | null;
  onDraftChange: (field: NasKeeperExecutionFromPreviewDraftField, value: string) => void;
  onStateDraftChange: (field: keyof NasKeeperExecutionStateDraft, value: string) => void;
  onApprovalChange: (approved: boolean) => void;
  onRecordStateAfterWriteChange: (enabled: boolean) => void;
  onExecute: () => void;
  onRecordState: () => void;
}) {
  const executionFields: NasKeeperExecutionFromPreviewDraftField[] = ["handoff_ref", "relay_execution_ref", "nas_keeper_ref", "relay_node_ref", "relay_authorized_by", "relay_authorized_at"];
  const stateFields: Array<keyof NasKeeperExecutionStateDraft> = ["execution_record_ref", "recorded_by", "recorded_at", "execution_status", "safe_summary", "evidence_refs"];

  return (
    <Card
      data-office-nas-keeper-execution-operator-action="true"
      data-office-nas-keeper-execution-operator-enabled-controls={action.enabledControls}
      data-office-nas-keeper-execution-operator-execution-endpoint={action.executionEndpoint}
      data-office-nas-keeper-execution-operator-state-endpoint={action.executionStateEndpoint}
      data-office-nas-keeper-execution-operator-markdown-body-projected={String(action.markdownBodyProjected)}
      data-office-nas-keeper-execution-operator-vps-nas-authority-enabled={String(action.vpsNasAuthorityEnabled)}
      data-office-nas-keeper-execution-operator-watcher-cron-daemon-enabled={String(action.watcherCronDaemonEnabled)}
      data-office-nas-keeper-execution-operator-inline-record-default={String(recordStateAfterWrite)}
      data-office-nas-keeper-execution-operator-approval-default={String(approved)}
      data-office-nas-keeper-execution-operator-request-safe-fields="handoff_ref,relay_execution_ref,nas_keeper_ref,relay_node_ref,relay_authorized_by,relay_authorized_at,record_execution_state_after_write,execution_record_ref,recorded_by,recorded_at"
      data-office-nas-keeper-execution-operator-relay-dispatch-enabled={String(action.relayDispatchEnabled)}
      data-office-nas-keeper-execution-operator-authority-adapter-binding-enabled={String(action.authorityAdapterBindingEnabled)}
    >
      <CardHeader>
        <CardTitle className="flex items-center gap-2 text-base">
          <ShieldCheck className="h-4 w-4 text-amber-300" /> {action.title}
        </CardTitle>
      </CardHeader>
      <CardContent>
        <div className="space-y-3 text-xs text-midground/75">
          <div className="border border-amber-300/20 bg-amber-950/10 p-3">
            <div className="font-semibold text-amber-100">execution-from-preview · safe queue item only</div>
            <div className="mt-1 leading-5">{action.safeSummary}</div>
            <div className="mt-1 grid gap-1 font-mono text-[10px] text-amber-100/70">
              <span>{action.executionEndpoint}</span>
              <span>{action.executionStateEndpoint}</span>
            </div>
          </div>
          <div className="grid gap-2 md:grid-cols-2">
            {executionFields.map((field) => (
              <label key={field} className="grid gap-1 border border-current/15 bg-black/15 p-2">
                <span className="font-mono text-[10px] uppercase tracking-[0.14em] text-midground/55">{field}</span>
                <input name={field} value={draft[field]} onChange={(event) => onDraftChange(field, event.target.value)} className="border border-current/15 bg-black/30 px-2 py-1 text-xs text-foreground" />
              </label>
            ))}
          </div>
          <label className="flex items-center gap-2 border border-amber-300/20 bg-amber-950/10 p-3 text-amber-100/80">
            <input type="checkbox" name="execution_from_preview_approved" checked={approved} onChange={(event) => onApprovalChange(event.target.checked)} />
            승인: authorized queue item을 preview 재검증 후 1회 실행
          </label>
          <label className="flex items-center gap-2 border border-sky-300/20 bg-sky-950/10 p-3 text-sky-100/80">
            <input type="checkbox" name="record_execution_state_after_write" checked={recordStateAfterWrite} onChange={(event) => onRecordStateAfterWriteChange(event.target.checked)} />
            성공한 write는 같은 요청에서 실행 상태까지 기록
          </label>
          <button type="button" disabled={!approved || busy} onClick={onExecute} className="border border-amber-300/30 px-3 py-2 text-xs font-semibold uppercase tracking-[0.14em] text-amber-100 disabled:opacity-40">
            {busy ? "실행 중" : recordStateAfterWrite ? "NAS Keeper → Mac relay 실행+기록" : "NAS Keeper → Mac relay preview 실행"}
          </button>
          <div className="grid gap-2 md:grid-cols-2">
            {stateFields.map((field) => (
              <label key={field} className="grid gap-1 border border-current/15 bg-black/15 p-2">
                <span className="font-mono text-[10px] uppercase tracking-[0.14em] text-midground/55">{field}</span>
                <input name={field} value={stateDraft[field]} onChange={(event) => onStateDraftChange(field, event.target.value)} className="border border-current/15 bg-black/30 px-2 py-1 text-xs text-foreground" />
              </label>
            ))}
          </div>
          <button type="button" disabled={stateBusy} onClick={onRecordState} className="border border-sky-300/30 px-3 py-2 text-xs font-semibold uppercase tracking-[0.14em] text-sky-100 disabled:opacity-40">
            {stateBusy ? "기록 중" : "실행 상태 기록"}
          </button>
          {error ? <div className="border border-red-300/25 bg-red-950/10 p-3 text-red-100" data-office-nas-keeper-execution-operator-error="true">{error}</div> : null}
          {result ? (
            <div className="border border-amber-300/20 bg-amber-950/10 p-3" data-office-nas-keeper-execution-operator-result="true">
              <div>executed {String(result.executed)} · written {String(result.written)}</div>
              {result.dto ? <div className="mt-1">handoff {result.dto.handoff_ref} · readback {String(result.dto.readback_verified)} · audit {String(result.dto.audit_written)}</div> : null}
              {result.errors.length > 0 ? <div className="mt-1">errors {result.errors.map((item) => `${item.field}:${item.code}`).join(" · ")}</div> : null}
            </div>
          ) : null}
          {stateResult ? (
            <div className="border border-sky-300/20 bg-sky-950/10 p-3" data-office-nas-keeper-execution-operator-state-result="true">
              recorded {String(stateResult.recorded)} · {stateResult.dto?.queue_status_after ?? "state_not_recorded"}
            </div>
          ) : null}
        </div>
      </CardContent>
    </Card>
  );
}

